306	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
307	// 不可为空、集合不可为空且编号不可重复。
308	func cleanParcelList(raw []string) ([]string, error) {
309		if len(raw) == 0 {
310			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
311		}
312		clean := make([]string, 0, len(raw))
313		seen := make(map[string]bool, len(raw))
314		for _, v := range raw {
315			id, err := cleanID("包裹编号", v)
316			if err != nil {
317				return nil, err
318			}
319			if seen[id] {
320				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
321			}
322			seen[id] = true
323			clean = append(clean, id)
324		}
325		return clean, nil
326	}
