386	func cmdReceipt(dataFile string, argv []string, stdout, stderr io.Writer) int {
387		fs := newFlagSet("receipt", stderr)
388		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
389		request := fs.String("request", "", "回执请求号（用于去重）")
390		batch := fs.String("batch", "", "配送批次号")
391		parcel := fs.String("parcel", "", "包裹编号")
392		result := fs.String("result", "", "回执结果：签收 或 失败")
393		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
394		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
395			return code
396		}
397	
398		cleanReq, err := cleanID("回执请求号", *request)
399		if err != nil {
400			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
401			return exitBusiness
402		}
403		cleanBatch, err := cleanID("批次号", *batch)
404		if err != nil {
405			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
406			return exitBusiness
407		}
408		cleanParcel, err := cleanID("包裹编号", *parcel)
409		if err != nil {
410			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
411			return exitBusiness
412		}
413		cleanResult, err := cleanID("回执结果", *result)
414		if err != nil {
415			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
416			return exitBusiness
417		}
418		if cleanResult != resultSigned && cleanResult != resultFailed {
419			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
420			return exitBusiness
421		}
422		cleanReason := strings.TrimSpace(*reason)
423		if cleanResult == resultFailed && cleanReason == "" {
424			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
425			return exitBusiness
426		}
427		if cleanResult == resultSigned && cleanReason != "" {
428			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
429			return exitBusiness
430		}
431	
432		store, release, err := OpenForUpdate(dataFile)
433		if err != nil {
434			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
435			return exitBusiness
436		}
437		defer release()
438		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
439		if err != nil {
440			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
441			return exitBusiness
442		}
443	
444		headline := "回执成功"
445		if replayed {
446			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
447			if res.RevokedBy != "" {
448				headline = "回执成功（请求号重复提交，返回首次保存的结果；该回执已撤销，未恢复回执或改变当前状态）"
449			}
450		}
451		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
452			headline, res.Request, res.Batch, res.Parcel, res.Result)
453		if res.Result == resultFailed {
454			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
455		}
456		if res.RevokedBy != "" {
457			fmt.Fprintf(stdout, "撤销状态: 已撤销（撤销请求号: %s）\n", res.RevokedBy)
458		}
459		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
460		return exitOK
461	}
