1093	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
1094	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
1095	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
1096	func coordinationPath(path string) (string, error) {
1097		abs, err := filepath.Abs(path)
1098		if err != nil {
1099			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
1100		}
1101		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
1102			abs = resolved
1103		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
1104			abs = filepath.Join(dir, filepath.Base(abs))
1105		}
1106		return abs + ".lock", nil
1107	}
1108	
1109	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
1110	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
1111	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
1112	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
1113	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
1114	// 无需人工删除协调文件即可继续作业。
1115	func OpenForUpdate(path string) (s *Store, release func(), err error) {
1116		lockPath, err := coordinationPath(path)
1117		if err != nil {
1118			return nil, nil, err
1119		}
1120		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
1121			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
1122		}
1123		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
1124		if err != nil {
1125			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
1126		}
1127		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
1128			_ = lock.Close()
1129			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
1130		}
1131		release = func() {
1132			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
1133			_ = lock.Close()
1134		}
1135		s, err = Open(path)
1136		if err != nil {
1137			release()
1138			return nil, nil, err
1139		}
1140		return s, release, nil
1141	}
