1188	// Handoff 提交一次多件包裹的站点交接。
1189	//
1190	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1191	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1192	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1193	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1194	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1195		if saved, ok := s.data.Handoffs[request]; ok {
1196			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1197				return saved, true, nil
1198			}
1199			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1200		}
1201	
1202		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1203		for _, id := range parcels {
1204			p, ok := s.data.Parcels[id]
1205			if !ok {
1206				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1207			}
1208			if p.Station != from {
1209				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1210			}
1211			if inc := activeFreeze(p); inc != "" {
1212				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1213			}
1214			if p.Status != statusInStation {
1215				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1216			}
1217		}
1218	
1219		res := &HandoffResult{
1220			Request: request,
1221			From:    from,
1222			To:      to,
1223			Parcels: append([]string(nil), parcels...),
1224			Time:    now,
1225		}
1226		s.data.Handoffs[request] = res
1227	
1228		// 记录旧值，落盘失败时整体回滚。
1229		prev := make(map[string]struct {
1230			station string
1231			trail   []Event
1232		}, len(parcels))
1233		for _, id := range parcels {
1234			p := s.data.Parcels[id]
1235			prev[id] = struct {
1236				station string
1237				trail   []Event
1238			}{p.Station, append([]Event(nil), p.Trail...)}
1239			p.Station = to
1240			p.Status = statusInStation
1241			p.Trail = append(p.Trail, Event{
1242				Op:      "交接",
1243				Station: to,
1244				Request: request,
1245				Time:    now,
1246			})
1247		}
1248	
1249		if err := s.save(); err != nil {
1250			delete(s.data.Handoffs, request)
1251			for id, old := range prev {
1252				p := s.data.Parcels[id]
1253				p.Station = old.station
1254				p.Trail = old.trail
1255			}
1256			return nil, false, err
1257		}
1258		return res, false, nil
1259	}
