1261	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1262	//
1263	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1264	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1265	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1266	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1267	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1268	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1269	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1270	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1271		if saved, ok := s.data.Returns[request]; ok {
1272			if saved.Handoff == handoffReq && saved.Reason == reason {
1273				return saved, true, nil
1274			}
1275			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1276				request, saved.Handoff, saved.Reason)
1277		}
1278	
1279		h, ok := s.data.Handoffs[handoffReq]
1280		if !ok {
1281			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1282		}
1283		if h.ReturnedBy != "" {
1284			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1285		}
1286	
1287		// 先做全部校验，任何一件不满足都整批拒绝。
1288		for _, id := range h.Parcels {
1289			p, ok := s.data.Parcels[id]
1290			if !ok {
1291				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1292			}
1293			if inc := activeFreeze(p); inc != "" {
1294				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1295			}
1296			if p.Station != h.To || p.Status != statusInStation {
1297				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1298					id, p.Station, p.Status, h.To)
1299			}
1300			last := lastFlowEvent(p.Trail)
1301			if last.Op != "交接" || last.Request != handoffReq {
1302				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1303					id, handoffReq)
1304			}
1305		}
1306	
1307		res := &ReturnResult{
1308			Request: request,
1309			Handoff: handoffReq,
1310			From:    h.To,
1311			To:      h.From,
1312			Reason:  reason,
1313			Parcels: append([]string(nil), h.Parcels...),
1314			Time:    now,
1315		}
1316		s.data.Returns[request] = res
1317		h.ReturnedBy = request
1318	
1319		// 记录旧值，落盘失败时整体回滚。
1320		prev := make(map[string]struct {
1321			station string
1322			trail   []Event
1323		}, len(h.Parcels))
1324		for _, id := range h.Parcels {
1325			p := s.data.Parcels[id]
1326			prev[id] = struct {
1327				station string
1328				trail   []Event
1329			}{p.Station, append([]Event(nil), p.Trail...)}
1330			p.Station = h.From
1331			p.Status = statusInStation
1332			p.Trail = append(p.Trail, Event{
1333				Op:         "退回",
1334				Station:    h.From,
1335				From:       h.To,
1336				Request:    request,
1337				RefRequest: handoffReq,
1338				Reason:     reason,
1339				Time:       now,
1340			})
1341		}
1342	
1343		if err := s.save(); err != nil {
1344			delete(s.data.Returns, request)
1345			h.ReturnedBy = ""
1346			for id, old := range prev {
1347				p := s.data.Parcels[id]
1348				p.Station = old.station
1349				p.Trail = old.trail
1350			}
1351			return nil, false, err
1352		}
1353		return res, false, nil
1354	}
