1356	// Dispatch 提交一次配送批次出站。
1357	//
1358	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1359	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1360	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1361	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1362	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1363	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1364		if saved, ok := s.data.Batches[batch]; ok {
1365			if saved.RelayedFrom != "" {
1366				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1367					batch, saved.RelayRequest, saved.RelayedFrom)
1368			}
1369			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1370				return saved, true, nil
1371			}
1372			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1373		}
1374	
1375		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1376		for _, id := range parcels {
1377			p, ok := s.data.Parcels[id]
1378			if !ok {
1379				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1380			}
1381			if p.Station != station {
1382				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1383			}
1384			if inc := activeFreeze(p); inc != "" {
1385				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1386			}
1387			if p.Status != statusInStation {
1388				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1389			}
1390		}
1391	
1392		res := &BatchResult{
1393			Batch:    batch,
1394			Station:  station,
1395			Courier:  courier,
1396			Parcels:  append([]string(nil), parcels...),
1397			Time:     now,
1398			Receipts: map[string]*ReceiptEntry{},
1399		}
1400		s.data.Batches[batch] = res
1401	
1402		// 记录旧值，落盘失败时整体回滚。
1403		prev := make(map[string]struct {
1404			status string
1405			trail  []Event
1406		}, len(parcels))
1407		for _, id := range parcels {
1408			p := s.data.Parcels[id]
1409			prev[id] = struct {
1410				status string
1411				trail  []Event
1412			}{p.Status, append([]Event(nil), p.Trail...)}
1413			p.Status = statusDelivering // 站点不变，仍记出发站
1414			p.Trail = append(p.Trail, Event{
1415				Op:      "出站",
1416				Station: station,
1417				Batch:   batch,
1418				Courier: courier,
1419				Time:    now,
1420			})
1421		}
1422	
1423		if err := s.save(); err != nil {
1424			delete(s.data.Batches, batch)
1425			for id, old := range prev {
1426				p := s.data.Parcels[id]
1427				p.Status = old.status
1428				p.Trail = old.trail
1429			}
1430			return nil, false, err
1431		}
1432		return res, false, nil
1433	}
