1754			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1755		}
1756		if p.Status != statusInStation {
1757			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1758		}
1759	
1760		res = &FreezeResult{
1761			Incident: incident,
1762			Parcel:   parcel,
1763			Station:  station,
1764			Reason:   reason,
1765			Time:     now,
1766		}
1767		s.data.Freezes[incident] = res
1768	
1769		// 记录旧值，落盘失败时整体回滚。
1770		oldStatus := p.Status
1771		oldTrail := append([]Event(nil), p.Trail...)
1772		p.Status = statusFrozen // 站点不变
1773		p.Trail = append(p.Trail, Event{
1774			Op:       "冻结",
1775			Station:  station,
1776			Incident: incident,
1777			Reason:   reason,
1778			Time:     now,
1779		})
1780	
1781		if err := s.save(); err != nil {
1782			delete(s.data.Freezes, incident)
1783			p.Status, p.Trail = oldStatus, oldTrail
1784			return nil, false, err
1785		}
1786		return res, false, nil
1787	}
