1789	// Unfreeze 解除一件包裹当前的异常冻结。
1790	//
1791	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1792	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1793	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1794	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1795	// 解除只是管理记录，不移动实物、不算新流转。
1796	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1797	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1798	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1799	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1800		if saved, ok := s.data.Unfreezes[request]; ok {
1801			if saved.Incident == incident && saved.Note == note {
1802				return saved, true, nil
1803			}
1804			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1805				request, saved.Incident, saved.Note)
1806		}
1807	
1808		f, ok := s.data.Freezes[incident]
1809		if !ok {
1810			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1811		}
1812		if f.ReleasedBy != "" {
1813			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1814		}
1815		p, ok := s.data.Parcels[f.Parcel]
1816		if !ok {
1817			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1818		}
1819		if p.Status != statusFrozen || activeFreeze(p) != incident {
1820			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1821				incident, f.Parcel, activeFreeze(p))
1822		}
1823	
1824		res = &UnfreezeResult{
1825			Request:  request,
1826			Incident: incident,
1827			Parcel:   f.Parcel,
1828			Note:     note,
1829			Time:     now,
1830		}
1831		s.data.Unfreezes[request] = res
1832		f.ReleasedBy = request
1833	
1834		// 记录旧值，落盘失败时整体回滚。
1835		oldStatus := p.Status
1836		oldTrail := append([]Event(nil), p.Trail...)
1837		p.Status = statusInStation // 在原站恢复在站，站点不变
1838		p.Trail = append(p.Trail, Event{
1839			Op:       "解除冻结",
1840			Station:  f.Station,
1841			Incident: incident,
1842			Request:  request,
1843			Note:     note,
1844			Time:     now,
1845		})
1846	
1847		if err := s.save(); err != nil {
1848			delete(s.data.Unfreezes, request)
1849			f.ReleasedBy = ""
1850			p.Status, p.Trail = oldStatus, oldTrail
1851			return nil, false, err
1852		}
1853		return res, false, nil
1854	}
