1856	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
1857	// 成员与站点取自原批次结果，不允许另选成员或站点。
1858	//
1859	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
1860	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
1861	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
1862	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
1863	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
1864	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
1865	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
1866	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
1867	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
1868	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
1869	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
1870	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
1871	// 失败的首次中止不占用请求号。
1872	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
1873		if saved, ok := s.data.Aborts[request]; ok {
1874			if saved.Batch == batch && saved.Reason == reason {
1875				return saved, true, nil
1876			}
1877			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
1878				request, saved.Batch, saved.Reason)
1879		}
1880	
1881		b, ok := s.data.Batches[batch]
1882		if !ok {
1883			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
1884		}
1885		if b.AbortedBy != "" {
1886			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
1887		}
1888		if b.TransferredBy != "" {
1889			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
1890		}
1891		if b.Done() {
1892			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
1893		}
1894	
1895		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
1896		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1897		for _, pid := range b.Parcels {
1898			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1899				recalled = append(recalled, pid)
1900			}
1901		}
1902		if len(recalled) == 0 {
1903			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
1904		}
1905	
1906		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1907		for _, pid := range recalled {
1908			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1909			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
1910				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
1911					pid, p.Station, p.Status, batch, b.Station)
1912			}
1913		}
1914	
1915		res = &AbortResult{
1916			Request: request,
1917			Batch:   batch,
1918			Station: b.Station,
1919			Reason:  reason,
1920			Parcels: recalled,
1921			Time:    now,
1922		}
1923		s.data.Aborts[request] = res
1924		b.AbortedBy = request
1925	
1926		// 记录旧值，落盘失败时整体回滚。
1927		prev := make(map[string]struct {
1928			status string
1929			trail  []Event
1930		}, len(recalled))
1931		for _, pid := range recalled {
1932			p := s.data.Parcels[pid]
1933			prev[pid] = struct {
1934				status string
1935				trail  []Event
1936			}{p.Status, append([]Event(nil), p.Trail...)}
1937			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
1938			p.Trail = append(p.Trail, Event{
1939				Op:      "收回",
1940				Station: b.Station,
1941				Batch:   batch,
1942				Request: request,
1943				Reason:  reason,
1944				Time:    now,
1945			})
1946		}
1947	
1948		if err := s.save(); err != nil {
1949			delete(s.data.Aborts, request)
1950			b.AbortedBy = ""
1951			for pid, old := range prev {
1952				p := s.data.Parcels[pid]
1953				p.Status = old.status
1954				p.Trail = old.trail
1955			}
1956			return nil, false, err
1957		}
1958		return res, false, nil
1959	}
