1961	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
1962	func (s *Store) BatchAbort(batch string) *AbortResult {
1963		b, ok := s.data.Batches[batch]
1964		if !ok || b.AbortedBy == "" {
1965			return nil
1966		}
1967		return s.data.Aborts[b.AbortedBy]
1968	}
