1970	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
1971	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
1972	//
1973	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
1974	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
1975	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
1976	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
1977	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
1978	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
1979	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
1980	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
1981	// 配送前的旧交接。
1982	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
1983	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
1984	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
1985	// 冲突；失败的首次续接不占用请求号。
1986	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
1987		if saved, ok := s.data.Transfers[request]; ok {
1988			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
1989				return saved, true, nil
1990			}
1991			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
1992				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
1993		}
1994	
1995		b, ok := s.data.Batches[fromBatch]
1996		if !ok {
1997			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
1998		}
1999		if b.AbortedBy != "" {
2000			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
2001		}
2002		if b.TransferredBy != "" {
2003			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
2004		}
2005		if _, used := s.data.Batches[toBatch]; used {
2006			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
2007		}
2008		if courier == b.Courier {
2009			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
2010		}
2011	
2012		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
2013		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
2014		for _, pid := range b.Parcels {
2015			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
2016				moved = append(moved, pid)
2017			}
2018		}
2019		if len(moved) == 0 {
2020			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
2021		}
2022	
2023		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2024		for _, pid := range moved {
2025			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2026			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
2027				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
2028					pid, p.Station, p.Status, fromBatch, b.Station)
2029			}
2030		}
2031	
2032		res = &TransferResult{
2033			Request:     request,
2034			FromBatch:   fromBatch,
2035			ToBatch:     toBatch,
2036			Station:     b.Station,
2037			FromCourier: b.Courier,
2038			ToCourier:   courier,
2039			Reason:      reason,
2040			Parcels:     append([]string(nil), moved...),
2041			Time:        now,
2042		}
2043		s.data.Transfers[request] = res
2044		s.data.Batches[toBatch] = &BatchResult{
2045			Batch:        toBatch,
2046			Station:      b.Station,
2047			Courier:      courier,
2048			Parcels:      append([]string(nil), moved...),
2049			Time:         now,
2050			Receipts:     map[string]*ReceiptEntry{},
2051			RelayedFrom:  fromBatch,
2052			RelayRequest: request,
2053		}
2054		b.TransferredBy = request
2055	
2056		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
2057		prev := make(map[string][]Event, len(moved))
2058		for _, pid := range moved {
2059			p := s.data.Parcels[pid]
2060			prev[pid] = append([]Event(nil), p.Trail...)
2061			p.Trail = append(p.Trail, Event{
2062				Op:        "续接",
2063				Station:   b.Station,
2064				Batch:     toBatch,
2065				FromBatch: fromBatch,
2066				Courier:   courier,
2067				Request:   request,
2068				Reason:    reason,
2069				Time:      now,
2070			})
2071		}
2072	
2073		if err := s.save(); err != nil {
2074			delete(s.data.Transfers, request)
2075			delete(s.data.Batches, toBatch)
2076			b.TransferredBy = ""
2077			for pid, old := range prev {
2078				s.data.Parcels[pid].Trail = old
2079			}
2080			return nil, false, err
2081		}
2082		return res, false, nil
2083	}
