2099	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2100	//
2101	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2102	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2103	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2104	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2105	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2106	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2107	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2108	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2109	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2110		if saved, ok := s.data.Shipments[shipment]; ok {
2111			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2112				return saved, true, nil
2113			}
2114			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2115		}
2116	
2117		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2118		for _, id := range parcels {
2119			p, ok := s.data.Parcels[id]
2120			if !ok {
