2391	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
2392	func activeFreeze(p *Parcel) string {
2393		if p.Status != statusFrozen {
2394			return ""
2395		}
2396		for i := len(p.Trail) - 1; i >= 0; i-- {
2397			if p.Trail[i].Op == "冻结" {
