2405	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
2406	func lastFlowEvent(trail []Event) Event {
2407		for i := len(trail) - 1; i >= 0; i-- {
2408			switch trail[i].Op {
2409			case "冻结", "解除冻结":
2410				continue
2411			default:
2412				return trail[i]
2413			}
2414		}
