2441	func sameSet(a, b []string) bool {
2442		if len(a) != len(b) {
2443			return false
2444		}
2445		x := append([]string(nil), a...)
2446		y := append([]string(nil), b...)
2447		sort.Strings(x)
2448		sort.Strings(y)
2449		for i := range x {
2450			if x[i] != y[i] {
