2457	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
2458	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
2459	func (s *Store) save() error {
2460		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
2461			return fmt.Errorf("保存数据文件失败: %w", err)
2462		}
2463		buf, err := json.MarshalIndent(s.data, "", "  ")
2464		if err != nil {
2465			return fmt.Errorf("保存数据文件失败: %w", err)
2466		}
2467		buf = append(buf, '\n')
2468	
2469		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
2470		if err != nil {
2471			return fmt.Errorf("保存数据文件失败: %w", err)
2472		}
2473		tmpName := tmp.Name()
2474		cleanup := func() { _ = os.Remove(tmpName) }
2475	
2476		if _, err := tmp.Write(buf); err != nil {
2477			_ = tmp.Close()
2478			cleanup()
2479			return fmt.Errorf("保存数据文件失败: %w", err)
2480		}
2481		if err := tmp.Sync(); err != nil {
2482			_ = tmp.Close()
2483			cleanup()
2484			return fmt.Errorf("保存数据文件失败: %w", err)
2485		}
2486		if err := tmp.Close(); err != nil {
2487			cleanup()
2488			return fmt.Errorf("保存数据文件失败: %w", err)
2489		}
2490	
2491		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
2492		var check ledgerFile
2493		if err := json.Unmarshal(buf, &check); err != nil {
2494			cleanup()
2495			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
2496		}
2497	
2498		if err := os.Rename(tmpName, s.path); err != nil {
2499			cleanup()
2500			return fmt.Errorf("保存数据文件失败: %w", err)
2501		}
2502		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
2503			_ = dir.Sync()
2504			_ = dir.Close()
2505		}
2506		return nil
2507	}
