344		})
345		corruptLedger(t, path, raw, "接收成员缺失", func(m map[string]any) {
346			delete(receive(m, "RS1"), "parcels")
347		})
348		corruptLedger(t, path, raw, "接收成员不属原单", func(m map[string]any) {
349			receive(m, "RS1")["parcels"] = []any{"P404"}
350		})
351		corruptLedger(t, path, raw, "接收成员顺序与发运矛盾", func(m map[string]any) {
352			receive(m, "RS2")["parcels"] = []any{"P003", "P002"}
353		})
354		corruptLedger(t, path, raw, "全部接收标记缺失", func(m map[string]any) {
355			delete(shipment(m), "receivedBy")
356		})
357		corruptLedger(t, path, raw, "部分接收却标记全部接收", func(m map[string]any) {
358			// 只保留 RS1（部分接收），但运输单仍标记全部接收。
359			delete(m["receives"].(map[string]any), "RS2")
360			shipment(m)["receivedBy"] = "RS1"
361			p := m["parcels"].(map[string]any)
362			for _, id := range []string{"P002", "P003"} {
363				pm := p[id].(map[string]any)
364				trail := pm["trail"].([]any)
365				pm["trail"] = trail[:len(trail)-1] // 去掉接收轨迹
366				pm["station"] = "站点A"
367				pm["status"] = "站间在途"
368			}
369		})
370		corruptLedger(t, path, raw, "接收请求引用不存在的运输单", func(m map[string]any) {
371			receive(m, "RS1")["shipment"] = "S404"
372		})
373		corruptLedger(t, path, raw, "接收结果为 null", func(m map[string]any) {
374			m["receives"].(map[string]any)["RS1"] = nil
375		})
376		restoreLedger(t, path, raw)
377	}
