501		if code != 0 || !strings.Contains(out, "当前状态: 在站") || !strings.Contains(out, "当前站点: 站点B") ||
502			strings.Contains(out, "当前运输单") || !strings.Contains(out, "操作: 接收") {
503			t.Fatalf("已收件 query 不应误认仍归原单在途: code=%d out=%s", code, out)
