508			"--parcel", "P001", "--parcel", "P003")
509		if code != 0 || !strings.Contains(out, "重复提交") {
510			t.Fatalf("显式集合换序重放应返回首次结果: code=%d out=%s", code, out)
511		}
512		out, _, code = runCLI(t, dbPath, "receive", "--request", "RS2", "--shipment", "S1", "--station", "站点B")
513		if code != 0 || !strings.Contains(out, "接收成功") || !strings.Contains(out, "P002") ||
514			strings.Contains(out, "P001") {
515			t.Fatalf("不选成员应接收全部余件: code=%d out=%s", code, out)
516		}
517		out, _, code = runCLI(t, dbPath, "shipment", "--id", "S1")
518		if code != 0 || !strings.Contains(out, "运输单状态: 已接收") ||
